WITH base AS (SELECT (multiIf(dynamicType(attrs.`b`) != 'None', (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`b`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`b`), arrayExists(x -> x = 2, events.attrs.`b`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`b`), arrayExists(x -> x = 2, links.attrs.`b`.:Int64), multiIf(dynamicType(scope_attrs.`b`) != 'None', (coalesce(scope_attrs.`b`.:Int64 = 2, false) OR coalesce(scope_attrs.`b`.:Float64 = 2, false)), false)))))) AND (1) AS sel, name, kind, status_code, status_message, scope_name, scope_version, attrs, scope_attrs, events, links, resource_id, service, trace_id FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND (1)), res AS (SELECT resource_id, any(attrs) AS rattrs FROM tqd_cat.resources GROUP BY resource_id), tr AS (SELECT trace_id, max(root_service) AS root_service, max(root_name) AS root_name FROM tqd_cat.traces GROUP BY trace_id), kv AS (SELECT sel, 'span' AS scope, kv.1 AS key, if(startsWith(kv.2, '"'), JSONExtractString(kv.2), kv.2) AS value, transform(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], ['String', 'Int64', 'Float64', 'Bool'], ['string', 'int', 'double', 'bool'], if(startsWith(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], 'Array'), 'array', tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')])) AS type FROM (SELECT sel, attrs AS j, CAST(JSONAllPathsWithTypes(attrs) AS Map(String, String)) AS tmap FROM base) ARRAY JOIN JSONExtractKeysAndValuesRaw(toString(j)) AS kv UNION ALL SELECT sel, 'instrumentation' AS scope, kv.1 AS key, if(startsWith(kv.2, '"'), JSONExtractString(kv.2), kv.2) AS value, transform(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], ['String', 'Int64', 'Float64', 'Bool'], ['string', 'int', 'double', 'bool'], if(startsWith(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], 'Array'), 'array', tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')])) AS type FROM (SELECT sel, scope_attrs AS j, CAST(JSONAllPathsWithTypes(scope_attrs) AS Map(String, String)) AS tmap FROM base) ARRAY JOIN JSONExtractKeysAndValuesRaw(toString(j)) AS kv UNION ALL SELECT sel, 'resource' AS scope, kv.1 AS key, if(startsWith(kv.2, '"'), JSONExtractString(kv.2), kv.2) AS value, transform(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], ['String', 'Int64', 'Float64', 'Bool'], ['string', 'int', 'double', 'bool'], if(startsWith(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], 'Array'), 'array', tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')])) AS type FROM (SELECT sel, rattrs AS j, CAST(JSONAllPathsWithTypes(rattrs) AS Map(String, String)) AS tmap FROM (SELECT b.sel AS sel, r.rattrs AS rattrs FROM base AS b INNER JOIN res AS r USING (resource_id))) ARRAY JOIN JSONExtractKeysAndValuesRaw(toString(j)) AS kv UNION ALL SELECT sel, 'event' AS scope, kv.1 AS key, if(startsWith(kv.2, '"'), JSONExtractString(kv.2), kv.2) AS value, transform(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], ['String', 'Int64', 'Float64', 'Bool'], ['string', 'int', 'double', 'bool'], if(startsWith(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], 'Array'), 'array', tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')])) AS type FROM (SELECT sel, eattrs AS j, CAST(JSONAllPathsWithTypes(eattrs) AS Map(String, String)) AS tmap FROM (SELECT sel, ev.3 AS eattrs FROM base ARRAY JOIN events AS ev)) ARRAY JOIN JSONExtractKeysAndValuesRaw(toString(j)) AS kv UNION ALL SELECT sel, 'link' AS scope, kv.1 AS key, if(startsWith(kv.2, '"'), JSONExtractString(kv.2), kv.2) AS value, transform(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], ['String', 'Int64', 'Float64', 'Bool'], ['string', 'int', 'double', 'bool'], if(startsWith(tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')], 'Array'), 'array', tmap[replaceAll(replaceAll(kv.1, '%', '%25'), '.', '%2E')])) AS type FROM (SELECT sel, lattrs AS j, CAST(JSONAllPathsWithTypes(lattrs) AS Map(String, String)) AS tmap FROM (SELECT sel, lk.5 AS lattrs FROM base ARRAY JOIN links AS lk)) ARRAY JOIN JSONExtractKeysAndValuesRaw(toString(j)) AS kv UNION ALL SELECT sel, 'resource', 'service.name', service, 'string' FROM base UNION ALL SELECT sel, 'intrinsic', k, v, 'string' FROM (SELECT sel, ['name', 'kind', 'status', 'statusMessage', 'instrumentation:name', 'instrumentation:version'] AS ks, [toString(name), arrayElement(['unspecified', 'internal', 'server', 'client', 'producer', 'consumer'], least(toInt32(kind), 5) + 1), arrayElement(['unset', 'ok', 'error'], least(toInt32(status_code), 2) + 1), status_message, toString(scope_name), toString(scope_version)] AS vs FROM base) ARRAY JOIN ks AS k, vs AS v UNION ALL SELECT sel, 'intrinsic', k, v, 'string' FROM (SELECT b.sel AS sel, ['trace:rootService', 'trace:rootName'] AS ks, [toString(t.root_service), toString(t.root_name)] AS vs FROM base AS b INNER JOIN tr AS t USING (trace_id)) ARRAY JOIN ks AS k, vs AS v UNION ALL SELECT sel, 'event', 'name', toString(ev.2), 'string' FROM base ARRAY JOIN events AS ev UNION ALL SELECT sel, 'link', k, v, 'string' FROM (SELECT sel, ['traceId', 'spanId'] AS ks, [lower(hex(lk.1)), lower(hex(lk.2))] AS vs FROM base ARRAY JOIN links AS lk) ARRAY JOIN ks AS k, vs AS v) SELECT scope, key, value, type, side, n FROM (SELECT scope, key, value, type, if(sel, 'selection', 'baseline') AS side, count() AS n, row_number() OVER (PARTITION BY scope, key, side ORDER BY count() DESC, value ASC, type ASC) AS rn FROM kv GROUP BY scope, key, value, type, side) WHERE rn <= 3 ORDER BY scope, key, side, n DESC, value, type FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
